package android.widget;import android.content.res.ColorStateList;public class SeekBar extends android.view.View{public ColorStateList thumb=ColorStateList.valueOf(103),progress=ColorStateList.valueOf(104),bg=ColorStateList.valueOf(105);public SeekBar(android.content.Context c){super(c);}public ColorStateList getThumbTintList(){return thumb;}public ColorStateList getProgressTintList(){return progress;}public ColorStateList getProgressBackgroundTintList(){return bg;}public void setThumbTintList(ColorStateList c){thumb=c;}public void setProgressTintList(ColorStateList c){progress=c;}public void setProgressBackgroundTintList(ColorStateList c){bg=c;}}
